"use strict";

const utils = require('../../../utils');
const fs = require('fs');

const allowedProperties = {
  attachment: true,
  url: true,
  sticker: true,
  emoji: true,
  emojiSize: true,
  body: true,
  mentions: true,
  location: true,
};

module.exports = (defaultFuncs, api, ctx) => {
  async function uploadAttachment(attachments) {
    var uploads = [];
    for (var i = 0; i < attachments.length; i++) {
        let attachment = attachments[i];
        let filename = "image.gif"; // Default filename
        
        // Kiểm tra nếu là Stream (có thuộc tính path)
        if (attachment && attachment.path && typeof attachment.path === 'string') {
            filename = attachment.path.split('/').pop() || "image.gif";
            console.log("📄 Detected stream with filename:", filename);
            // DO NOT modify attachment.path for streams - let axios.js extract filename using path.basename()
        }
        
        // Đọc file từ đường dẫn thành Buffer để tránh lỗi Stream Node 24
        if (typeof attachment === 'string') {
            try { 
                filename = attachment.split('/').pop() || "image.gif"; // Get filename from path
                attachment = fs.readFileSync(attachment); 
            } catch (e) {}
        }
        
        // Đặt path giả nếu thiếu (để axios.js bắt được và xử lý filename)
        if (attachment && !attachment.path) {
             attachment.path = filename;
        }

        console.log("📎 Attachment path:", attachment?.path);

        // Kiểm tra loại file - chỉ dùng voice_clip cho audio
        let uploadParams = {
            upload_1024: attachment
        };
        
        // Chỉ thêm voice_clip nếu là file audio
        if (filename.includes('.mp3') || filename.includes('.m4a') || filename.includes('.ogg') || filename.includes('.wav')) {
            console.log("🎵 Detected audio file:", filename);
            uploadParams.voice_clip = "true";
        } else {
            console.log("🖼️ Detected image file:", filename);
        }

        const oksir = await defaultFuncs.postFormData("https://upload.facebook.com/ajax/mercury/upload.php", ctx.jar, uploadParams, {}).then(utils.parseAndCheckLogin(ctx, defaultFuncs));
        
        console.log("🔍 Upload response:", JSON.stringify(oksir, null, 2));
        
        if (oksir.error) throw new Error(JSON.stringify(oksir));

        if (oksir.payload && oksir.payload.metadata) {
            // Find the relevant metadata entry - prefer audio, then video, then gif, then image, then file
            let selectedMeta = null;
            
            Object.keys(oksir.payload.metadata).forEach(key => {
                const meta = oksir.payload.metadata[key];
                if (meta) {
                    // Priority: audio > video > gif > image > file
                    if (meta.audio_id && !selectedMeta?.audio_id) {
                        selectedMeta = meta;
                        console.log(`✅ Selected audio metadata[${key}]:`, JSON.stringify(meta, null, 2));
                    } else if (meta.video_id && !selectedMeta?.audio_id && !selectedMeta?.video_id) {
                        selectedMeta = meta;
                    } else if (meta.gif_id && !selectedMeta?.audio_id && !selectedMeta?.video_id && !selectedMeta?.gif_id) {
                        selectedMeta = meta;
                        console.log(`✅ Selected gif metadata[${key}]:`, JSON.stringify(meta, null, 2));
                    } else if (meta.image_id && !selectedMeta?.audio_id && !selectedMeta?.video_id && !selectedMeta?.gif_id && !selectedMeta?.image_id) {
                        selectedMeta = meta;
                    } else if (meta.file_id && !selectedMeta) {
                        selectedMeta = meta;
                    }
                }
            });
            
            if (selectedMeta) {
                uploads.push(selectedMeta);
                console.log("📦 Using metadata:", JSON.stringify(selectedMeta, null, 2));
            } else {
                console.log("⚠️ No valid metadata found in upload response");
            }
        } else {
            console.log("⚠️ No metadata in upload response");
        }
    }
    return uploads;
  }

  async function getUrl(url) {
    const resData = await defaultFuncs.post("https://www.facebook.com/message_share_attachment/fromURI/", ctx.jar, {
      image_height: 960,
      image_width: 960,
      uri: url
    }).then(utils.parseAndCheckLogin(ctx, defaultFuncs));
    if (!resData || resData.error || !resData.payload) throw new Error(JSON.stringify(resData));
    return resData.payload.share_data.share_params;
  }

  async function sendContent(form, threadID, isSingleUser, messageAndOTID, callback) {
    if (utils.getType(threadID) === "Array") {
      for (var i = 0; i < threadID.length; i++) {
        form["specific_to_list[" + i + "]"] = "fbid:" + threadID[i];
      }
      form["specific_to_list[" + threadID.length + "]"] = "fbid:" + ctx.userID;
      form["client_thread_id"] = "root:" + messageAndOTID;
    } else {
      if (isSingleUser) {
        form["specific_to_list[0]"] = "fbid:" + threadID;
        form["specific_to_list[1]"] = "fbid:" + ctx.userID;
        form["other_user_fbid"] = threadID;
      } else {
        form["thread_fbid"] = threadID;
      }
    }

    if (ctx.globalOptions.pageID) {
      form["author"] = "fbid:" + ctx.globalOptions.pageID;
      form["specific_to_list[1]"] = "fbid:" + ctx.globalOptions.pageID;
      form["creator_info[creatorID]"] = ctx.userID;
      form["creator_info[creatorType]"] = "direct_admin";
      form["creator_info[labelType]"] = "sent_message";
      form["creator_info[pageID]"] = ctx.globalOptions.pageID;
      form["request_user_id"] = ctx.globalOptions.pageID;
      form["creator_info[profileURI]"] = "https://www.facebook.com/profile.php?id=" + ctx.userID;
    }

    const resData = await defaultFuncs.post("https://www.facebook.com/messaging/send/", ctx.jar, form).then(utils.parseAndCheckLogin(ctx, defaultFuncs));
    
    console.log("📤 Sending form to Facebook:");
    console.log("  - has_attachment:", form.has_attachment);
    console.log("  - audio_ids:", form.audio_ids);
    console.log("  - image_ids:", form.image_ids);
    console.log("  - body:", form.body);
    
    if (!resData) throw new Error("Send message failed.");
    if (resData.error) {
        console.log("❌ Facebook API Error Response:", JSON.stringify(resData, null, 2));
        throw new Error("Facebook API Error: " + resData.error);
    }
    
    const messageInfo = resData.payload.actions.reduce((p, v) => {
      return {
        threadID: v.thread_fbid,
        messageID: v.message_id,
        timestamp: v.timestamp
      } || p;
    }, null);
    return messageInfo;
  }

  return async (msg, threadID, replyToMessage, isSingleUser = false) => {
    let msgType = utils.getType(msg);
    if (msgType === "String") msg = { body: msg };
    
    let messageAndOTID = utils.generateOfflineThreadingID();
    let form = {
      client: "mercury",
      action_type: "ma-type:user-generated-message",
      author: "fbid:" + ctx.userID,
      timestamp: Date.now(),
      timestamp_absolute: "Today",
      timestamp_relative: utils.generateTimestampRelative(),
      timestamp_time_passed: "0",
      is_unread: false,
      is_cleared: false,
      is_forward: false,
      is_filtered_content: false,
      is_filtered_content_bh: false,
      is_filtered_content_account: false,
      is_filtered_content_quasar: false,
      is_filtered_content_invalid_app: false,
      is_spoof_warning: false,
      source: "source:chat:web",
      "source_tags[0]": "source:chat",
      ...(msg.body && { body: msg.body }),
      html_body: false,
      ui_push_phase: "V3",
      status: "0",
      offline_threading_id: messageAndOTID,
      message_id: messageAndOTID,
      threading_id: utils.generateThreadingID(ctx.clientID),
      "ephemeral_ttl_mode:": "0",
      manual_retry_cnt: "0",
      has_attachment: !!(msg.attachment || msg.url || msg.sticker),
      signatureID: utils.getSignatureID(),
      ...(replyToMessage && { replied_to_message_id: replyToMessage })
    };

    if (msg.location) {
        form["location_attachment[coordinates][latitude]"] = msg.location.latitude;
        form["location_attachment[coordinates][longitude]"] = msg.location.longitude;
        form["location_attachment[is_current_location]"] = !!msg.location.current;
    }
    if (msg.sticker) form["sticker_id"] = msg.sticker;
    
    if (msg.attachment) {
      form.image_ids = []; form.gif_ids = []; form.file_ids = []; form.video_ids = []; form.audio_ids = [];
      if (utils.getType(msg.attachment) !== "Array") msg.attachment = [msg.attachment];
      
      const files = await uploadAttachment(msg.attachment);
      
      // === FIX LOGIC PHÂN LOẠI ID ===
      files.forEach(file => {
          if (file) {
              console.log("📂 Processing file object:", JSON.stringify(file, null, 2));
              // Phân loại nghiêm ngặt: GIF phải vào gif_ids, Ảnh phải vào image_ids
              if (file.gif_id) {
                  console.log("✅ Found gif_id:", file.gif_id);
                  form.gif_ids.push(file.gif_id);
              } else if (file.image_id) {
                  console.log("✅ Found image_id:", file.image_id);
                  form.image_ids.push(file.image_id);
              } else if (file.video_id) {
                  console.log("✅ Found video_id:", file.video_id);
                  form.video_ids.push(file.video_id);
              } else if (file.audio_id) {
                  console.log("✅ Found audio_id:", file.audio_id);
                  form.audio_ids.push(file.audio_id);
              } else if (file.file_id) {
                  console.log("✅ Found file_id:", file.file_id);
                  form.file_ids.push(file.file_id);
              } else {
                   // Fallback cuối cùng
                   console.log("⚠️ No recognized ID, trying fallback");
                   const type = Object.keys(file)[0];
                   if (form["" + type + "s"]) form["" + type + "s"].push(file[type]);
              }
          }
      });
      console.log("📋 Form after file processing:", { audio_ids: form.audio_ids, image_ids: form.image_ids, gif_ids: form.gif_ids, file_ids: form.file_ids, video_ids: form.video_ids });
      // ==============================
    }

    if (msg.url) {
      form["shareable_attachment[share_type]"] = "100";
      const params = await getUrl(msg.url);
      form["shareable_attachment[share_params]"] = params;
    }
    
    console.log("🔵 Final form object before sending:", JSON.stringify({
        body: form.body,
        has_attachment: form.has_attachment,
        audio_ids: form.audio_ids,
        image_ids: form.image_ids,
        gif_ids: form.gif_ids,
        file_ids: form.file_ids,
        video_ids: form.video_ids
    }, null, 2));
    
    // === FIX: Convert array IDs to indexed form parameters ===
    // Facebook expects: gif_ids[0], gif_ids[1], etc. instead of array
    const arrayFields = ['audio_ids', 'image_ids', 'gif_ids', 'file_ids', 'video_ids'];
    arrayFields.forEach(field => {
        if (Array.isArray(form[field]) && form[field].length > 0) {
            const ids = form[field];
            delete form[field];  // Remove array
            ids.forEach((id, index) => {
                form[field + '[' + index + ']'] = id;
            });
            console.log(`✅ Converted ${field} to indexed parameters:`, ids);
        }
    });
    // ========================================================
    
    if (msg.emoji) {
      if (!msg.emojiSize) msg.emojiSize = "medium";
      form.body = msg.emoji;
      form["tags[0]"] = "hot_emoji_size:" + msg.emojiSize;
    }
    if (msg.mentions) {
       for (let i = 0; i < msg.mentions.length; i++) {
        const mention = msg.mentions[i];
        const tag = mention.tag;
        const offset = msg.body.indexOf(tag, mention.fromIndex || 0);
        const id = mention.id || 0;
        const emptyChar = '\u200E';
        form["body"] = emptyChar + msg.body;
        form["profile_xmd[" + i + "][offset]"] = offset + 1;
        form["profile_xmd[" + i + "][length]"] = tag.length;
        form["profile_xmd[" + i + "][id]"] = id;
        form["profile_xmd[" + i + "][type]"] = "p";
      }
    }
    return await sendContent(form, threadID, isSingleUser, messageAndOTID);
  };
};